import unittest

from hourglass.gaps import find_gaps
from hourglass.models import Span
from hourglass.parsing import parse_span

class FindGapsTests(unittest.TestCase):
    def test_middle_gap(self):
        worked = [
            parse_span("09:00-12:00"),
            parse_span("13:00-17:00")
        ]
        self.assertEqual(
            find_gaps(worked, parse_span("09:00-17:00")),
            ["gap 12:00-13:00 (60 min)"]
        )

    def test_edges_and_middle(self):
        worked = [Span(600, 660), Span(720, 780)]
        self.assertEqual(
            find_gaps(worked, Span(540, 840)),
            [
                "gap 09:00-10:00 (60 min)",
                "gap 11:00-12:00 (60 min)",
                "gap 13:00-14:00 (60 min)"
            ]
        )

    def test_nobody_worked(self):
        self.assertEqual(
            find_gaps([], Span(540, 600)),
            ["gap 09:00-10:00 (60 min)"]
        )

    def test_full_coverage_has_no_gaps(self):
        worked = [Span(540, 700), Span(600, 720)]
        result = find_gaps(worked, Span(540, 720))
        self.assertEqual(result, [])

    def test_overlaps_do_not_hide_gaps(self):
        worked = [Span(540, 600), Span(570, 630)]
        self.assertEqual(
            find_gaps(worked, Span(540, 700)),
            ["gap 10:30-11:40 (70 min)"]
        )

    def test_span_before_opening_raises(self):
        with self.assertRaises(ValueError):
            find_gaps([Span(500, 600)], Span(540, 700))

    def test_span_after_closing_raises(self):
        with self.assertRaises(ValueError):
            find_gaps([Span(600, 800)], Span(540, 700))

if __name__ == "__main__":
    unittest.main()
